css:
.print-format { font-family: "Helvetica Neue", Arial, sans-serif; font-size: 9.5pt; color: #000; }
.yht-head { width: 100%; border-bottom: 2px solid #000; margin-bottom: 6px; }
.yht-head td { vertical-align: top; padding: 2px 0 6px; }
.yht-head-en, .yht-head-ar { width: 50%; }
.yht-co { font-size: 13pt; font-weight: bold; }
.yht-sub { font-size: 8.5pt; }
.yht-title { text-align: center; font-size: 13pt; font-weight: bold; letter-spacing: 1px; margin: 6px 0 2px; }
.yht-title-ar { text-align: center; font-size: 12pt; margin-bottom: 8px; direction: rtl; }
.yht-copy { text-align: center; font-size: 8pt; text-transform: uppercase; letter-spacing: 2px; border: 1px solid #000; display: inline-block; padding: 1px 8px; }
.yht-copy-wrap { text-align: center; margin-bottom: 8px; }
.yht-meta { width: 100%; margin-bottom: 8px; border-collapse: collapse; }
.yht-meta td { border: 1px solid #999; padding: 3px 5px; font-size: 9pt; }
.yht-meta .lbl { background: #f2f2f2; font-weight: bold; width: 15%; }
.yht-party-name { font-weight: bold; font-size: 10pt; }
table.yht-items { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
table.yht-items th, table.yht-items td { border: 1px solid #999; padding: 3px 5px; font-size: 9pt; }
table.yht-items th { background: #f2f2f2; text-align: center; }
table.yht-items td.num { text-align: right; }
table.yht-items td.ctr { text-align: center; }
.yht-ar-cell { direction: rtl; text-align: right; font-size: 9pt; }
.yht-totals { width: 45%; margin-left: auto; border-collapse: collapse; }
.yht-totals td { border: 1px solid #999; padding: 3px 6px; font-size: 9pt; }
.yht-totals td.lbl { background: #f2f2f2; font-weight: bold; }
.yht-totals td.num { text-align: right; }
.yht-grand td { font-weight: bold; font-size: 10pt; }
.yht-words { font-size: 8.5pt; font-style: italic; margin: 6px 0; }
.yht-sign { width: 100%; margin-top: 28px; border-collapse: collapse; }
.yht-sign td { width: 33%; font-size: 8.5pt; padding-top: 4px; border-top: 1px solid #000; text-align: center; }
.yht-note { font-size: 8pt; color: #444; margin-top: 10px; }
.page-break { page-break-after: always; }
